async fn resolve_dispatch_ref(
    shared: &Arc<SharedState>,
    repository: &str,
    selected_ref: Option<&str>,
    default_branch: &str,
) -> Result<(String, &'static str), ApiError> {
    let Some(raw) = selected_ref else {
        return Ok((format!("refs/heads/{default_branch}"), "branch"));
    };
