        return Ok((branch_ref, "branch"));
    }
    let tag_ref = format!("refs/tags/{raw}");
    if resolve_ref_sha(shared, repository, &tag_ref)
        .await
        .map_err(|error| ApiError::bad_gateway(format!("failed to resolve {tag_ref}: {error}")))?
        .is_some()
